import numpy as np

def seed(rep):
    return int(np.random.SeedSequence(13, spawn_key=(0, rep)).generate_state(1)[0])

first = [seed(r) for r in range(3)]
more = [seed(r) for r in range(10)]
print(more[:3] == first)

class B:
    def __init__(self, limit):
        self.limit, self.spent = limit, 0
    def reserve(self, amount):
        if self.spent + amount > self.limit:
            raise RuntimeError("over")
        self.spent += amount

b = B(300_000)
for cost in (384_000, 50_000, 12_000, 28_000, 148_000, 32_000):
    try:
        b.reserve(cost)
    except RuntimeError:
        pass
print(b.spent)
